() => {
  const items = document.querySelectorAll('[data-component-type="s-search-result"]');
  const results = [];
  items.forEach((item, idx) => {
    const titleEl = item.querySelector('h2 a, h2 span');
    const title = titleEl ? titleEl.textContent.trim() : '';
    const priceWhole = item.querySelector('.a-price-whole');
    const priceFraction = item.querySelector('.a-price-fraction');
    const price = priceWhole ? '$' + priceWhole.textContent + (priceFraction ? priceFraction.textContent : '') : '';
    const ratingEl = item.querySelector('[aria-label*="out of 5 stars"]');
    const rating = ratingEl ? ratingEl.getAttribute('aria-label') : '';
    const reviewsEl = item.querySelector('a[aria-label*="ratings"]');
    const reviews = reviewsEl ? reviewsEl.getAttribute('aria-label') : '';
    const linkEl = item.querySelector('h2 a');
    const link = linkEl ? linkEl.getAttribute('href') : '';
    if (title) results.push({ idx, title: title.substring(0, 200), price, rating, reviews, link: link ? 'https://www.amazon.com' + link : '' });
  });
  return results.slice(0, 20);
}

() => {
  const items = document.querySelectorAll('[data-component-type="s-search-result"]');
  const results = [];
  items.forEach((item, idx) => {
    const titleEl = item.querySelector('h2 a, h2 span');
    const title = titleEl ? titleEl.textContent.trim() : '';
    const priceWhole = item.querySelector('.a-price-whole');
    const priceFraction = item.querySelector('.a-price-fraction');
    const price = priceWhole ? '$' + priceWhole.textContent.trim() + (priceFraction ? '.' + priceFraction.textContent.trim() : '') : 'N/A';
    const ratingEl = item.querySelector('[aria-label*="out of 5 stars"]');
    const rating = ratingEl ? ratingEl.getAttribute('aria-label') : '';
    const reviewsEl = item.querySelector('a[aria-label*="ratings"]');
    const reviews = reviewsEl ? reviewsEl.getAttribute('aria-label') : '';
    const linkEl = item.querySelector('h2 a');
    const link = linkEl ? linkEl.getAttribute('href') : '';
    if (title) results.push({ idx, title: title.substring(0, 200), price, rating, reviews, link: link ? 'https://www.amazon.com' + link : '' });
  });
  return JSON.stringify(results);
}

() => {
  const urlParams = new URLSearchParams(window.location.search);
  return JSON.stringify({
    url: window.location.href,
    rh: urlParams.get('rh'),
    p_36: urlParams.get('p_36'),
    resultCount: document.querySelector('.s-result-count')?.textContent?.trim() || 'not found'
  });
}
